import os


class Config:
    """
    Configuration for the Multi-Field Asymmetric Dual-Backbone Ensemble (MF-ADBE).
    """

    # Reproducibility
    SEED = 42

    # -------------------------------------------------------------------------
    # Paths
    # -------------------------------------------------------------------------
    # Input Data
    INPUT_TRAIN_JSON = "./input/train.json"
    INPUT_TEST_JSON = "./input/test.json"

    # Metadata (Generated by metadata script)
    METADATA_TRAIN = "./metadata/train.csv"
    METADATA_VAL = "./metadata/val.csv"
    METADATA_TEST = "./metadata/test.csv"

    # Working Directory (for caching intermediate files)
    WORKING_DIR = "./working/idea_39/"

    # Submission Directory
    SUBMISSION_DIR = "./submission/"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create directories if they don't exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Caching
    # -------------------------------------------------------------------------
    # Paths for cached processed features (Parquet) and embeddings (NPY)
    CACHE_TRAIN_FEATURES = os.path.join(WORKING_DIR, "train_features.parquet")
    CACHE_VAL_FEATURES = os.path.join(WORKING_DIR, "val_features.parquet")
    CACHE_TEST_FEATURES = os.path.join(WORKING_DIR, "test_features.parquet")

    # We store embeddings separately to avoid re-running expensive inference
    # Files will store a dictionary or stacked array of views
    CACHE_TRAIN_EMBEDDINGS = os.path.join(WORKING_DIR, "train_embeddings.npy")
    CACHE_VAL_EMBEDDINGS = os.path.join(WORKING_DIR, "val_embeddings.npy")
    CACHE_TEST_EMBEDDINGS = os.path.join(WORKING_DIR, "test_embeddings.npy")

    # -------------------------------------------------------------------------
    # Model Architectures
    # -------------------------------------------------------------------------
    # High-Resolution Anchors (Title View, Body View)
    MODEL_ANCHOR = "sentence-transformers/all-MiniLM-L6-v2"

    # Global Context Auxiliary (Combined View)
    MODEL_AUX = "sentence-transformers/all-mpnet-base-v2"

    # -------------------------------------------------------------------------
    # Feature Definitions
    # -------------------------------------------------------------------------
    # Text Columns
    TEXT_COL_TITLE = "request_title"
    TEXT_COL_BODY = "request_text_edit_aware"

    # Numerical Metadata Features
    NUMERICAL_FEATURES = [
        "requester_account_age_in_days_at_request",
        "requester_days_since_first_post_on_raop_at_request",
        "requester_number_of_comments_at_request",
        "requester_number_of_comments_in_raop_at_request",
        "requester_number_of_posts_at_request",
        "requester_number_of_posts_on_raop_at_request",
        "requester_number_of_subreddits_at_request",
        "requester_upvotes_minus_downvotes_at_request",
        "requester_upvotes_plus_downvotes_at_request",
        "unix_timestamp_of_request",  # Explicitly included per strategy
    ]

    # -------------------------------------------------------------------------
    # Hyperparameters
    # -------------------------------------------------------------------------
    # Dimensionality Reduction for Global Context (View 3)
    PCA_COMPONENTS_AUX = 50

    # Ensemble Settings
    N_BAGGING_ESTIMATORS = 20

    # Grid Search Space for Logistic Regression Base Estimator
    # Note: For sklearn BaggingClassifier, we tune the base estimator parameters.
    # In recent sklearn versions, the parameter is 'estimator', so we use 'estimator__param'.
    PARAM_GRID = {
        "estimator__C": [1e-4, 1e-3, 1e-2, 1e-1, 1.0, 10.0],
        "estimator__class_weight": ["balanced", None],
    }
